Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
ksmbd: fix durable fd leak on ClientGUID mismatch in durable
 v2 open

ksmbd_lookup_fd_cguid() returns a ksmbd_file with its refcount
incremented via ksmbd_fp_get(). parse_durable_handle_context() in
the DURABLE_REQ_V2 case properly releases this reference on every
path inside the ClientGUID-match branch, either by calling
ksmbd_put_durable_fd() or by transferring ownership to dh_info->fp
for a successful reconnect. However, when an entry exists in the
global file table with the same CreateGuid but a different
ClientGUID, the code simply falls through to the new-open path
without dropping the reference obtained from ksmbd_lookup_fd_cguid().

Per MS-SMB2 section 3.3.5.9.10 ("Handling the
SMB2_CREATE_DURABLE_HANDLE_REQUEST_V2 Create Context"), the server
MUST locate an Open whose Open.CreateGuid matches the request's
CreateGuid AND whose Open.ClientGuid matches the ClientGuid of the
connection that received the request. If no such Open is found, the
server MUST continue with the normal open execution phase. A
CreateGuid hit with a ClientGUID mismatch is therefore the
"Open not found" case: proceeding with a new open is correct, but
the reference obtained purely as a side effect of the lookup must
not be leaked.

Repeated requests that hit this mismatch pin global_ft entries,
prevent __ksmbd_close_fd() from ever running for the corresponding
files, and defeat the durable scavenger, leading to long-lived
resource leaks.

Release the reference in the mismatch path and clear dh_info->fp so
subsequent logic does not mistake a non-matching lookup result for
a reconnect target.

Fixes: c8efcc786146 ("ksmbd: add support for durable handles v1/v2")
Signed-off-by: DaeMyung Kang <charsyam@gmail.com>
Acked-by: Namjae Jeon <linkinjeon@kernel.org>
Signed-off-by: Steve French <stfrench@microsoft.com>

Here is the root cause:
In the DURABLE_REQ_V2 handling of parse_durable_handle_context(), when ksmbd_lookup_fd_cguid() finds an entry with a matching CreateGuid but a different ClientGUID, the code proceeds to the new-open path without releasing the reference count obtained from the lookup. This missing ksmbd_put_durable_fd() call causes a reference leak, pinning the global file table entry and preventing proper cleanup, including the durable scavenger. The leak is triggered because the reference obtained via ksmbd_fp_get() inside ksmbd_lookup_fd_cguid() is not decremented on the mismatch branch.

Here is the patch:

 static int parse_durable_handle_context(struct ksmbd_work *work,
 					struct smb2_create_req *req,
 					struct lease_ctx_info *lc,
 					struct durable_info *dh_info)
 {
 	struct ksmbd_conn *conn = work->conn;
 	struct create_context *context;
 	int dh_idx, err = 0;
 	u64 persistent_id = 0;
 	int req_op_level;
 	static const char * const durable_arr[] = {"DH2C", "DHnC", "DH2Q", "DHnQ"};

 	req_op_level = req->RequestedOplockLevel;
 	for (dh_idx = DURABLE_RECONN_V2; dh_idx <= ARRAY_SIZE(durable_arr);
 	     dh_idx++) {
 		context = smb2_find_context_vals(req, durable_arr[dh_idx - 1], 4);
 		if (IS_ERR(context)) {
 			err = PTR_ERR(context);
 			goto out;
 		}
 		if (!context)
 			continue;

 		switch (dh_idx) {
 		case DURABLE_RECONN_V2:
 		{
 			struct create_durable_handle_reconnect_v2 *recon_v2;

 			if (dh_info->type == DURABLE_RECONN ||
 			    dh_info->type == DURABLE_REQ_V2) {
 				err = -EINVAL;
 				goto out;
 			}

 			if (le16_to_cpu(context->DataOffset) +
 				le32_to_cpu(context->DataLength) <
 			    sizeof(struct create_durable_handle_reconnect_v2)) {
 				err = -EINVAL;
 				goto out;
 			}

 			recon_v2 = (struct create_durable_handle_reconnect_v2 *)context;
 			persistent_id = recon_v2->dcontext.Fid.PersistentFileId;
 			dh_info->fp = ksmbd_lookup_durable_fd(persistent_id);
 			if (!dh_info->fp) {
 				ksmbd_debug(SMB, "Failed to get durable handle state\n");
 				err = -EBADF;
 				goto out;
 			}

 			if (memcmp(dh_info->fp->create_guid, recon_v2->dcontext.CreateGuid,
 				   SMB2_CREATE_GUID_SIZE)) {
 				err = -EBADF;
 				ksmbd_put_durable_fd(dh_info->fp);
 				goto out;
 			}

 			dh_info->type = dh_idx;
 			dh_info->reconnected = true;
 			ksmbd_debug(SMB,
 				"reconnect v2 Persistent-id from reconnect = %llu\n",
 					persistent_id);
 			break;
 		}
 		case DURABLE_RECONN:
 		{
 			create_durable_reconn_t *recon;

 			if (dh_info->type == DURABLE_RECONN_V2 ||
 			    dh_info->type == DURABLE_REQ_V2) {
 				err = -EINVAL;
 				goto out;
 			}

 			if (le16_to_cpu(context->DataOffset) +
 				le32_to_cpu(context->DataLength) <
 			    sizeof(create_durable_reconn_t)) {
 				err = -EINVAL;
 				goto out;
 			}

 			recon = (create_durable_reconn_t *)context;
 			persistent_id = recon->Data.Fid.PersistentFileId;
 			dh_info->fp = ksmbd_lookup_durable_fd(persistent_id);
 			if (!dh_info->fp) {
 				ksmbd_debug(SMB, "Failed to get durable handle state\n");
 				err = -EBADF;
 				goto out;
 			}

 			dh_info->type = dh_idx;
 			dh_info->reconnected = true;
 			ksmbd_debug(SMB, "reconnect Persistent-id from reconnect = %llu\n",
 				    persistent_id);
 			break;
 		}
 		case DURABLE_REQ_V2:
 		{
 			struct create_durable_req_v2 *durable_v2_blob;

 			if (dh_info->type == DURABLE_RECONN ||
 			    dh_info->type == DURABLE_RECONN_V2) {
 				err = -EINVAL;
 				goto out;
 			}

 			if (le16_to_cpu(context->DataOffset) +
 				le32_to_cpu(context->DataLength) <
 			    sizeof(struct create_durable_req_v2)) {
 				err = -EINVAL;
 				goto out;
 			}

 			durable_v2_blob =
 				(struct create_durable_req_v2 *)context;
 			ksmbd_debug(SMB, "Request for durable v2 open\n");
 			dh_info->fp = ksmbd_lookup_fd_cguid(durable_v2_blob->dcontext.CreateGuid);
 			if (dh_info->fp) {
 				if (!memcmp(conn->ClientGUID, dh_info->fp->client_guid,
 					    SMB2_CLIENT_GUID_SIZE)) {
 					if (!(req->hdr.Flags & SMB2_FLAGS_REPLAY_OPERATION)) {
 						err = -ENOEXEC;
 						ksmbd_put_durable_fd(dh_info->fp);
 						goto out;
 					}

 					if (dh_info->fp->conn) {
 						ksmbd_put_durable_fd(dh_info->fp);
 						err = -EBADF;
 						goto out;
 					}
 					dh_info->reconnected = true;
 					goto out;
 				}
+				ksmbd_put_durable_fd(dh_info->fp);
+				dh_info->fp = NULL;
 			}

 			if ((lc && (lc->req_state & SMB2_LEASE_HANDLE_CACHING_LE)) ||
 			    req_op_level == SMB2_OPLOCK_LEVEL_BATCH) {
 				dh_info->CreateGuid =
 					durable_v2_blob->dcontext.CreateGuid;
 				dh_info->persistent =
 					le32_to_cpu(durable_v2_blob->dcontext.Flags);
 				dh_info->timeout =
 					le32_to_cpu(durable_v2_blob->dcontext.Timeout);
 				dh_info->type = dh_idx;
 			}
 			break;
 		}
 		case DURABLE_REQ:
 			if (dh_info->type == DURABLE_RECONN)
 				goto out;
 			if (dh_info->type == DURABLE_RECONN_V2 ||
 			    dh_info->type == DURABLE_REQ_V2) {
 				err = -EINVAL;
 				goto out;
 			}

 			if ((lc && (lc->req_state & SMB2_LEASE_HANDLE_CACHING_LE)) ||
 			    req_op_level == SMB2_OPLOCK_LEVEL_BATCH) {
 				ksmbd_debug(SMB, "Request for durable open\n");
 				dh_info->type = dh_idx;
 			}
 		}
 	}

 out:
 	return err;
 }



